/* Extend the existing vanilla application; preserve its importer, staircase, and academic rules. */
let productFilters={query:'',kind:'All'},previewQuarter=0;
function productCoverage(){return `<div class="note">Verified coverage is limited: UWB Electrical Engineering foundation/core requirements and selected Bellevue → UW mappings. Other institutions are research links, not verified degree plans. <a class="text-link" href="#sources">See sources and limits →</a></div>`}
function productHome(){return `<section class="hero">${caminoWorld()}<div class="hero-copy"><div class="eyebrow">CAMINO / YOUR FUTURE. YOUR DIRECTION.</div><h1>Find your major.<br>Choose your college.<br><em>Build your future.</em></h1><p class="lede">Discover three college and career paths that match your interests, then build a personalized academic roadmap with Washington course equivalencies, application deadlines, and internship milestones.</p><p class="hero-scope">Selected equivalencies are sourced. Deadlines require official confirmation; internship milestones are your planning tasks.</p><div class="actions">${btn('Take the Camino Quiz','discover',true)}${btn('Preview a Student Roadmap','preview')}</div><ul class="hero-promises"><li>Free to explore</li><li>No account required to start</li><li>Built for Washington students</li><li>Transcript upload is optional</li></ul></div></section><section class="section" id="how"><div class="eyebrow">ONE JOURNEY. THREE STEPS.</div><h2>A clearer next step starts here.</h2><div class="steps">${[['Discover','Complete an interactive career and major discovery assessment.','discover'],['Explore','Compare majors, colleges, and sourced transfer pathways.','colleges'],['Plan','Turn confirmed coursework and your goals into a quarter-by-quarter roadmap.','profile']].map(([title,copy,route],i)=>`<article class="step"><span class="number">0${i+1}</span><h3>${title}</h3><p>${copy}</p>${btn(title+' →',route)}</article>`).join('')}</div></section><section class="section journey-examples"><div class="eyebrow">DIFFERENT STARTING POINTS. YOUR OWN PACE.</div><h2>Where are you starting?</h2><p class="muted">Illustrative journeys, not testimonials or promises of admission.</p><div class="grid">${[['Ninth grader','Explore strengths, try a club, and discuss course options with a counselor.'],['High school senior','Compare institutions and research university and major admission separately.'],['Running Start student','Review high school graduation and college transfer requirements with both advisors.'],['Community college student','Reconcile completed courses and explore the supported UWB EE roadmap.'],['University student','Check separate competitive-major prerequisites and application milestones.']].map(([title,copy])=>`<article class="card"><span class="tag">ILLUSTRATIVE JOURNEY</span><h3>${title}</h3><p>${copy}</p><a class="text-link" href="#discover">Find your direction →</a></article>`).join('')}</div></section><section class="section"><h2>Washington first. Coverage made clear.</h2>${productCoverage()}<div class="grid">${ProductCore.institutions.map(u=>`<article class="card"><h3>${esc(u.name)}</h3><p>${esc(u.coverage)}</p><a class="text-link" href="${u.url}" target="_blank" rel="noopener">Official institution ↗</a></article>`).join('')}</div></section>`}
function productPreview(){const example={courses:[],profile:{major:'Electrical Engineering',target:AcademicPathway.UWB,load:'Balanced',summer:false,startTerm:'Fall',startYear:2027}};const p=AcademicPathway.plan(example,'Balanced'),count=Math.max(...p.courses.map(c=>c.term))+1;previewQuarter=Math.min(previewQuarter,count-1);return page('ILLUSTRATIVE ROADMAP / NO STUDENT RECORDS','See a plan before you start.',`<p class="lede">An example UWB EE foundation/core roadmap with no completed coursework. This is not your plan or a complete degree audit.</p><div class="subnav">${Array.from({length:Math.min(count,6)},(_,i)=>`<button class="chip ${i===previewQuarter?'active':''}" data-preview-quarter="${i}" aria-pressed="${i===previewQuarter}">${ProductCore.termName(example.profile,i)}</button>`).join('')}</div><div class="grid">${p.courses.filter(c=>c.term===previewQuarter).map(c=>`<article class="card"><span class="tag">ILLUSTRATIVE · OFFERING UNCONFIRMED</span><h3>${esc(c.displayCode||c.code)}</h3><p>${esc(c.title)} · ${c.credits} quarter credits</p><p>${esc(c.institution)}</p><p>${esc(c.explanation)}</p><a href="${c.source}" class="text-link" target="_blank" rel="noopener">Published requirement ↗</a></article>`).join('')}</div>${productCoverage()}<div class="actions">${btn('Discover my three paths','discover',true)}${btn('Build my own roadmap','profile')}</div>`)}
let catalogRankingCache={key:null,rows:null};function allCatalogRecommendations(){const key=(state.answers||[]).join('|')+'#'+ProgramCatalog.programs.length;if(catalogRankingCache.key!==key)catalogRankingCache={key,rows:CatalogPathfinder.rank(state.answers||[],ProgramCatalog.programs,ProductCore.questions)};return catalogRankingCache.rows}
function recommendationDetails(p){const base=E.majors.find(m=>m.name===p.name)||{};return{...base,...p,description:'Explore '+p.name+' at '+p.institution+'.',skills:base.skills||'Read the published curriculum and try introductory coursework or a related project.',outcomes:base.outcomes||'Career paths depend on the exact program, credential and further preparation.',education:p.credential||p.kind,industry:base.industry||p.domains.join(' · '),work:base.work||'Confirm workload in the published curriculum.',tradeoff:base.tradeoff||'Program requirements, selection policies and availability need individual review.'}}
function currentRecommendations(){return CatalogPathfinder.shortlist(allCatalogRecommendations(),3).map(recommendationDetails)}

function quizSessionWrite(){const draft={length:quizLength,answers:[...answers],index:quizIndex};try{sessionStorage.setItem('camino-quiz-session',JSON.stringify(draft))}catch{}if(accountUser){state.quizDraft=draft;save()}}
function restoreQuiz(){let raw;try{raw=JSON.parse(sessionStorage.getItem('camino-quiz-session')||'null')}catch{}const draft=ProductCore.quizDraft(raw||state.quizDraft);if(draft&&draft.answers.length<draft.length){answers=draft.answers;quizIndex=draft.index;quizLength=draft.length;return true}return false}
function quizFinish(){state.answers=[...answers];state.results=currentRecommendations().map(m=>({name:m.name,programId:m.programId,institution:m.institution}));state.quizHistory||=[];state.quizHistory.unshift({at:new Date().toISOString(),answers:[...answers],majors:state.results.map(m=>m.name)});state.quizHistory=state.quizHistory.slice(0,10);delete state.quizDraft;try{sessionStorage.removeItem('camino-quiz-session')}catch{}save();location.hash='results';render()}
function productQuestion(){if(!answers.length&&quizIndex===0)restoreQuiz();if(quizIndex>=quizLength)quizIndex=quizLength-1;const q=ProductCore.questions[quizIndex];return `<section class="quiz">${pathAtmosphere(quizIndex)}<div class="quiz-content"><div class="row"><a class="text-link" href="#discover">← Save & leave quiz</a><span class="tag">${quizIndex+1} / ${quizLength}</span></div><div class="progress" role="progressbar" aria-label="Quiz progress" aria-valuemin="0" aria-valuemax="${quizLength}" aria-valuenow="${quizIndex}"><div style="width:${quizIndex/quizLength*100}%"></div></div><span class="eyebrow">${esc(q.category)}</span><h1 id="quiz-prompt" tabindex="-1">${esc(q.prompt)}</h1><div class="choices">${q.choices.map((label,i)=>`<button class="choice ${answers[quizIndex]===q.tags[i]?'selected':''}" data-product-answer="${q.tags[i]}" aria-pressed="${answers[quizIndex]===q.tags[i]}"><small>0${i+1}</small><span class="choice-copy">${esc(label)}</span></button>`).join('')}</div><div class="actions"><button class="btn" id="product-quiz-back" ${quizIndex===0?'disabled':''}>← Previous question</button><button class="motion-control" data-toggle-motion>${state.reduceMotion?'Enable':'Pause'} motion</button></div><p class="muted">Choices save in this tab’s session. Signed-in Sites accounts also save an unfinished draft. This is exploratory, not a validated assessment.</p></div></section>`}
function pathwayResources(m){return `<p><strong>Washington research starting points:</strong></p>${ProductCore.institutions.filter(u=>u.kind==='University').map(u=>`<a class="text-link resource-link" href="${u.programs}" target="_blank" rel="noopener">${esc(u.name)} program directory ↗</a>`).join('')}<p>Program availability and admission must be checked for this major. Bellevue, Cascadia, and Seattle Colleges can be researched as community-college starting points; no unverified equivalency is implied.</p>`}
function productResults(){const rec=currentRecommendations();return page('YOUR THREE POSSIBLE FUTURES','Three directions. Room to grow.',`<p class="lede">Interest fit is a conversation starter, separate from academic readiness and admission. No compatibility percentages or admission chances are calculated.</p><div class="grid">${rec.map((m,i)=>`<article class="card pathway-card"><span class="tag">PATH ${i+1} · EXPLORATORY</span><h3>${esc(m.name)}</h3><p>${esc(m.description)}</p><h4>Why this direction?</h4><p>Your answers emphasized ${esc(m.tags.join(' and '))}. Each selected interest adds one point to that theme; majors sum their two themes.</p><p><strong>Strengths to develop:</strong> ${esc(m.skills)}</p><p><strong>Careers / industry:</strong> ${esc(m.outcomes)} · ${esc(m.industry)}</p><p><strong>Education:</strong> ${esc(m.education)}</p><p><strong>Preparation:</strong> Try an introductory project, review relevant math/science or writing preparation, and confirm program requirements with an advisor.</p>${pathwayResources(m)}<div class="actions"><button class="btn primary" data-major="${esc(m.key||m.name)}">Choose this direction</button><button class="btn" data-save-pathway="${esc(m.name)}">${(state.savedPathways||[]).includes(m.name)?'Saved ✓':'Save path'}</button></div><label>Replace this recommendation<select data-replace-pathway="${i}"><option value="">Choose an alternative…</option>${catalogDirectionOptions('')}</select></label></article>`).join('')}</div><div class="actions">${btn('Compare these three paths','explore',true)}${btn('Explore colleges','colleges')}${btn('Retake the quiz','discover')}</div><details class="card"><summary>Scoring, limitations & previous results</summary><p>Six exploratory themes: build, logic, people, create, research, lead. A choice adds one point to its theme. A major’s two theme counts are added. Ties follow the documented major-list order. Work preferences contextualize reflection; they do not establish ability, licensing eligibility or admission. The questionnaire is not scientifically validated.</p>${(state.quizHistory||[]).map((run,i)=>`<div class="quiz-history"><strong>${esc(new Date(run.at).toLocaleDateString())}</strong><p>${(run.majors||[]).map(esc).join(' · ')}</p><button class="btn" data-load-quiz="${i}">Compare this result</button></div>`).join('')||'<p>Complete a quiz to keep a result snapshot.</p>'}</details><div class="card"><h3>Your saved directions</h3><p>${(state.savedPathways||[]).map(esc).join(' · ')||'Save a path above to return to it.'}</p></div>${productCoverage()}`)}
function collegeDirectory(){const filtered=ProductCore.institutions.filter(u=>(productFilters.kind==='All'||u.kind===productFilters.kind)&&(u.name+' '+u.location).toLowerCase().includes(productFilters.query.toLowerCase()));return page('EXPLORE COLLEGES','Choose a place to take your next step.',`<p class="lede">Search Washington institutions and compare official research resources. Selecting a school does not imply verified major availability or admission eligibility.</p><form class="card form-grid" id="college-search"><div><label for="college-query">Name or location</label><input id="college-query" name="query" value="${esc(productFilters.query)}"></div><div><label for="college-kind">Institution type</label><select id="college-kind" name="kind">${options(['All','University','Community college'],productFilters.kind)}</select></div><button class="btn">Filter institutions</button></form><p role="status">${filtered.length} institutions found</p><div class="grid">${filtered.map(u=>`<article class="card"><span class="tag">${esc(u.location)} · ${u.calendar}</span><h3>${esc(u.name)}</h3><p>${esc(u.coverage)}</p><a class="text-link" href="${u.admissions}" target="_blank" rel="noopener">Official admissions ↗</a><label><input type="checkbox" data-compare-college="${esc(u.name)}" ${(state.collegeCompare||[]).includes(u.name)?'checked':''}> Compare this college (up to three)</label>${u.kind==='University'?`<button class="btn" data-target-college="${esc(u.name)}">Use as my target</button>`:''}</article>`).join('')||'<div class="empty">No institutions match. Try a shorter name or another type.</div>'}</div>${collegeComparison()}${productCoverage()}`)}
function collegeComparison(){const selected=(state.collegeCompare||[]).map(name=>ProductCore.institutions.find(u=>u.name===name)).filter(Boolean);return selected.length?`<h2>College comparison</h2><div class="table-wrap" tabindex="0" role="region" aria-label="College comparison"><table><thead><tr><th>Research topic</th>${selected.map(u=>`<th scope="col">${esc(u.name)}</th>`).join('')}</tr></thead><tbody>${[['Location','location'],['Calendar','calendar'],['Coverage','coverage']].map(([label,key])=>`<tr><th scope="row">${label}</th>${selected.map(u=>`<td>${esc(u[key])}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">University / direct / competitive major / transfer admission</th>${selected.map(u=>`<td>Separate processes; confirm your student type and program.<br><a href="${u.admissions}" class="text-link" target="_blank" rel="noopener">Official admissions ↗</a></td>`).join('')}</tr><tr><th scope="row">Costs, dates & program availability</th>${selected.map(u=>`<td>Not verified for your entry year. No estimates asserted. <a class="text-link" href="${u.url}" target="_blank" rel="noopener">Research official tuition and calendar ↗</a></td>`).join('')}</tr></tbody></table></div>`:''}
function recordPlanChange(message){state.planChanges||=[];state.planChanges.unshift({at:new Date().toISOString(),message});state.planChanges=state.planChanges.slice(0,12);if(state.manual){state.archivedPlans||=[];state.archivedPlans.unshift({at:new Date().toISOString(),reason:message,courses:state.manual});state.archivedPlans=state.archivedPlans.slice(0,3);}state.manual=null;state.manualSignature=null;}
function productBuildPlan(input=state,load=mode,useManual=true){const academic=AcademicPathway.plan(input,load),limit={Balanced:15,Flexible:10,Accelerated:20}[load]||15;let result=academic.supported?academic:{...E.schedule(input.courses.filter(c=>!c.completed&&c.status!=='Dropped'&&c.status!=='Failed').map(c=>({code:c.code,title:c.title,institution:c.institution,credits:c.credits,prereqs:c.prereqs||[]})),E.completedCodes(input.courses,input.profile?.target),limit),supported:false,done:[],remaining:[]};const sig=ProductCore.signature(input,load);if(useManual&&Array.isArray(input.manual)&&input.manualMode===load&&input.manualSignature===sig)result={...result,courses:result.courses.map(c=>({...c,term:input.manual.find(m=>m.code===c.code)?.term??c.term})),method:'Your adjusted, validated schedule'};result={...result,errors:ProductCore.validatePlan(result.courses,academic.supported?academic.done:E.completedCodes(input.courses,input.profile?.target),input.profile||{},limit)};if(!academic.supported)result.coverage='No verified institutional degree rules for this major, institution or semester selection. This is a draft of student-entered courses only.';return result}
function progressPanel(plan){const current=state.courses.filter(c=>c.status==='In progress').length,remaining=plan.remaining?.length||plan.courses.length,completed=plan.done?.length||state.courses.filter(E.passing).length;return `<section class="card progress-audit"><span class="tag">UNOFFICIAL PROGRESS / SUPPORTED REQUIREMENTS ONLY</span><h3>Your record, in five views.</h3><div class="progress-counts">${[['Completed',completed],['Currently taking',current],['Planned',plan.courses.length],['Remaining',remaining],['Needs verification',plan.courses.length+(plan.blocked?.length||0)]].map(([label,n])=>`<div><strong>${n}</strong><span>${label}</span></div>`).join('')}</div><p>Counts overlap: planned courses are also remaining requirements. Completed/remaining count supported requirements; currently taking counts your course records. Every future offering needs confirmation. In-progress courses are not earned credit. General education, residency, total credits, transfer applicability and catalog-year rules need an official degree audit.</p>${plan.coverage?`<div class="note">${esc(plan.coverage)}</div>`:''}${plan.errors.length?`<div class="note" role="alert"><strong>Schedule conflicts — do not treat this draft as registration-ready.</strong><ul>${plan.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<details><summary>What changed?</summary>${(state.planChanges||[]).map(x=>`<p>${esc(x.message)}</p>`).join('')||'<p>No recorded changes yet. Recalculating does not remove completed coursework.</p>'}</details></section>`}
function productProfile(){const p=state.profile||{};return page('YOUR GOALS','Start where you are.',`<p class="lede">A transcript is optional. Add only the details you want to use for planning.</p><form id="product-profile" class="card form-wrap"><div class="form-grid"><div><label for="p-name">Name (optional)</label><input id="p-name" name="name" maxlength="40" value="${esc(p.name)}"></div><div><label for="p-grade">Current education level / year</label><select id="p-grade" name="grade">${options(grades,p.grade)}</select></div><div><label for="p-institution">Current institution (optional)</label><select id="p-institution" name="institution"><option value="">Not selected</option>${options(schools,p.institution)}</select></div><div><label for="p-second">Also taking classes at (optional)</label><input id="p-second" name="second" maxlength="100" value="${esc(p.second)}" placeholder="e.g. Bellevue College"></div><div><label for="p-major">Major to explore</label>${catalogDirectionControl('p-major',p.major||currentRecommendations()[0].name,p.primaryProgramId||'')}</div><div><label for="p-target">Target university</label><select id="p-target" name="target">${options(ProductCore.institutions.filter(u=>u.kind==='University').map(u=>u.name),p.target)}</select></div><div><label for="p-year">Graduation goal (optional, not a prediction)</label><input id="p-year" name="year" type="number" min="2026" max="2050" value="${esc(p.year)}"></div><div><label for="p-start">First planned term</label><select id="p-start" name="startTerm">${options(['Fall','Winter','Spring','Summer'],p.startTerm||'Winter')}</select></div><div><label for="p-start-year">First planned year</label><input id="p-start-year" name="startYear" type="number" min="2026" max="2050" required value="${esc(p.startYear||2027)}"></div><div><label for="p-calendar">Academic calendar</label><select id="p-calendar" name="calendar">${options(['Quarter','Semester'],p.calendar||'Quarter')}</select></div><div><label for="p-load">Credit workload</label><select id="p-load" name="load">${options(['Flexible','Balanced','Accelerated'],p.load||'Balanced')}</select></div><div><label for="p-max">Preferred maximum courses per term (optional)</label><input id="p-max" name="maxCourses" type="number" min="1" max="8" value="${esc(p.maxCourses)}"></div><div><label for="p-transfer">Transfer intention</label><select id="p-transfer" name="transferIntent">${options(['Exploring','Planning to transfer','Already at target university','Not transferring'],p.transferIntent)}</select></div></div><label for="p-goals">Academic goals / career interests (optional)</label><textarea id="p-goals" name="goals" maxlength="1000">${esc(p.goals)}</textarea><label><input type="checkbox" name="summer" ${p.summer?'checked':''}> Include summer terms</label><label><input type="checkbox" name="preferCommunity" ${p.preferCommunity?'checked':''}> Prefer sourced Bellevue equivalents</label><p class="muted">Quarter degree rules are enabled only for UWB EE. Semester plans support manual coursework in semester units; no credit conversion or institutional degree audit is inferred.</p><p id="profile-error" role="alert"></p><button class="btn primary">Save goals & build roadmap →</button></form>${productCoverage()}`,true)}
function recordStatusControls(){return `<section class="card"><h3>Update your academic record</h3><p>Marking a class in progress, dropped or failed does not count it as earned credit. Failed/excluded attempts remain in the audit history.</p>${state.courses.map((c,i)=>`<div class="record-status-row"><strong>${esc(c.code)} · ${esc(c.institution)}</strong><label>Status<select data-record-status="${i}">${options(['Planned','In progress','Completed','Dropped','Failed'],c.status||(c.completed?'Completed':'Planned'))}</select></label><label>Grade (optional)<input data-record-grade="${i}" value="${esc(c.grade)}" maxlength="20"></label></div>`).join('')||'<p>Add a course manually or confirm a transcript import first.</p>'}</section>`}
function productScenarios(){const p=state.profile||{};return page('WHAT IF? / YOUR ORIGINAL STAYS SAVED','Try another staircase.',`<p class="lede">Compare a proposal against your current roadmap. Unsupported majors or institutions show missing coverage, rather than invented requirements.</p><form id="product-scenario" class="card form-wrap"><div class="form-grid"><div><label for="s-name">Scenario name</label><input id="s-name" name="name" maxlength="80" required></div><div><label for="s-major">Proposed major</label>${catalogDirectionControl('s-major',p.major,p.primaryProgramId||'')}</div><div><label for="s-target">Proposed university</label><select id="s-target" name="target">${options(ProductCore.institutions.filter(u=>u.kind==='University').map(u=>u.name),p.target)}</select></div><div><label for="s-load">Workload</label><select id="s-load" name="load">${options(['Flexible','Balanced','Accelerated'],p.load||mode)}</select></div><div><label for="s-repeat">Repeat a completed course (simulation only)</label><select id="s-repeat" name="repeat"><option value="">No repeat</option>${state.courses.filter(E.passing).map(c=>`<option value="${esc(c.code)}">${esc(c.code)}</option>`).join('')}</select></div><div><label for="s-year">Proposed graduation goal</label><input id="s-year" name="year" type="number" min="2026" max="2050" value="${esc(p.year)}"></div></div><label><input type="checkbox" name="summer" ${p.summer?'checked':''}> Include summer</label><button class="btn primary">Save comparison</button></form><div class="grid scenario-list">${(state.scenarios||[]).map((s,i)=>`<article class="card"><h3>${esc(s.name)}</h3><p>${esc(s.profile?.major||s.load)} · ${esc(s.profile?.target||'Earlier workload scenario')}</p>${s.delta?`<p>${s.delta.baseTerms} → ${s.delta.terms} planned terms. This is not a degree-completion estimate.</p><p>Added: ${s.delta.added.map(esc).join(', ')||'None in known coverage'}</p><p>Removed from this draft: ${s.delta.removed.map(esc).join(', ')||'None'}</p><p>Moved / school changed: ${s.delta.moved.map(esc).join(', ')||'None'}</p><p>Conflicts: ${s.delta.conflicts.map(esc).join('; ')||'None detected in entered constraints'}</p>${s.supported?'':'<div class="note">Proposed degree rules unavailable. Missing generated courses do not mean those requirements disappeared. Verify transfer and major admission separately.</div>'}`:`<p>${s.terms||0} draft terms · Earlier saved workload comparison.</p>`}<button class="btn" data-delete-scenario="${i}">Delete comparison</button></article>`).join('')||'<div class="empty">No saved scenarios. Try changing summer availability first.</div>'}</div><p class="note">Comparisons are snapshots. They do not change completed coursework or your original goals. A graduation-year change alone does not waive prerequisites. Major and transfer admission remain separate reviews.</p>`,true)}
function productMilestones(){return page('TRACK YOUR NEXT STEPS','Make the next deadline a smaller step.',`<p class="lede">Keep university admission, major admission, financial aid and career preparation separate. No institutional deadlines are pre-verified for your entry term.</p><div class="grid">${[['University admission','Review the official application window for your student type.'],['Major admission','Check direct admission, competitive entry and prerequisite timing.'],['Financial aid / scholarships','Research official aid and scholarship dates for your year.'],['Advising / registration','Confirm course offerings, prerequisites and dual-enrollment policies.'],['Career / internships','Draft a résumé, document a project, and research employer eligibility.']].map(([label,copy])=>`<article class="card"><h3>${label}</h3><p>${copy}</p>${tasks([label+': '+copy])}</article>`).join('')}</div><form id="milestone-form" class="card form-wrap"><h3>Add your milestone</h3><div class="form-grid"><div><label for="m-title">Task</label><input id="m-title" name="title" required maxlength="150"></div><div><label for="m-kind">Category</label><select id="m-kind" name="category">${options(['University admission','Major admission','Financial aid','Scholarship','Registration','Advising','Internship','Résumé / portfolio','Career fair'])}</select></div><div><label for="m-date">Your planning date</label><input id="m-date" type="date" name="date" required></div><div><label for="m-source">Official source URL (optional, HTTPS)</label><input id="m-source" name="source" type="url" placeholder="https://" maxlength="1000"></div></div><p>Dates you enter are personal planning dates, not Camino-verified deadlines. Downloading a calendar event does not schedule background notifications.</p><button class="btn primary">Save milestone</button></form><div class="grid scenario-list">${(state.milestones||[]).map((m,i)=>`<article class="card"><span class="tag">PERSONAL PLANNING DATE · NOT VERIFIED</span><h3>${esc(m.title)}</h3><p>${esc(m.category)} · ${esc(m.date)}</p>${ProductCore.safeURL(m.source)?`<a class="text-link" target="_blank" rel="noopener" href="${esc(ProductCore.safeURL(m.source))}">Your source ↗</a>`:''}<label><input type="checkbox" data-milestone-done="${i}" ${m.done?'checked':''}> Completed</label><button class="btn" data-milestone-calendar="${i}">Download calendar event</button><button class="btn" data-milestone-delete="${i}">Delete</button></article>`).join('')}</div><h2>Official admissions resources</h2>${ProductCore.institutions.filter(u=>u.kind==='University').map(u=>`<p><a class="text-link" target="_blank" rel="noopener" href="${u.admissions}">${esc(u.name)} ↗</a></p>`).join('')}`,true)}
function productPrivacy(){return page('YOUR DATA, YOUR CONTROL','Keep your future yours.',`<div class="card form-wrap"><h3>What is saved</h3><p>${standaloneMode?'This standalone site has no account backend. Reviewed courses, goals, results, milestones and scenarios save in this browser only.':'On Sites, signed-in workspaces use private account-scoped storage. Guests save in this browser. Account sign-in is provided by Sites.'} Clearing site storage removes local work. Export a backup before switching devices or URLs.</p><p>Original transcript PDFs/images and full extracted transcript text are processed locally. Only reviewed course records save with the workspace. The separate optional application review sends your statement, prompt and activities to Cloudflare Workers AI only after consent; completed course codes, titles and grades are included only if you opt in. Original files are not uploaded. Application drafts save separately in this browser only when you choose Save; they are excluded from workspace sync and backup exports, and Delete all my data removes them. English OCR may misread records. Delete all my data clears imported document data and resets this page.</p><p>Unfinished anonymous quiz answers use session storage. Completed results save in browser storage. This browser profile’s users can access local records. Avoid shared-device storage and do not enter student IDs, birth dates or unnecessary sensitive data.</p><p>No analytics or email/push notification service is configured. External institutions and Google Fonts have their own network/privacy policies. No claim of COPPA, FERPA or other legal compliance is made; a legal review, age-appropriate consent and institutional agreements may be required before wider service to minors.</p><p><strong>Start fresh:</strong> Delete all my data removes Camino records and drafts from this browser and your saved workspace if signed in. It cannot remove backups you downloaded, copies on other devices, or information already processed by external services.</p><div class="actions"><button class="btn" id="export-data">Export my data ↓</button><button class="btn" id="delete-data">Delete all my data</button></div></div>`)}
function resetProductForm(selector){const node=document.querySelector(selector);if(!node)return null;const copy=node.cloneNode(true);node.replaceWith(copy);return copy}
function bindProduct(){
 resetProductForm('#retry-account')?.addEventListener('click',async()=>{if(!accountUser)return;accountError='';accountDirty=true;await flushAccount();render()});
 document.querySelector('#recover-workspace')?.addEventListener('click',()=>download('camino-recovery.json',globalThis.caminoRecoveryRaw||'', 'application/json'));
 document.querySelectorAll('[data-apply-scenario]').forEach(el=>el.onclick=()=>toast('Saved comparisons do not overwrite your original plan. Edit your goals explicitly to apply a new direction.'));
 document.querySelectorAll('[data-start]').forEach(el=>el.onclick=()=>{answers=[];quizIndex=0;quizLength=+el.dataset.start;quizSessionWrite();location.hash='quiz';render()});
 document.querySelector('#resume-quiz')?.addEventListener('click',()=>{restoreQuiz();location.hash='quiz';render()});
 document.querySelectorAll('[data-product-answer]').forEach(el=>el.onclick=()=>{if(el.disabled)return;el.disabled=true;answers[quizIndex]=el.dataset.productAnswer;quizIndex++;if(quizIndex>=quizLength)quizFinish();else{quizSessionWrite();render();document.querySelector('#quiz-prompt')?.focus({preventScroll:true})}});
 document.querySelector('#product-quiz-back')?.addEventListener('click',()=>{quizIndex=Math.max(0,quizIndex-1);quizSessionWrite();render()});
 document.querySelectorAll('[data-preview-quarter]').forEach(el=>el.onclick=()=>{previewQuarter=+el.dataset.previewQuarter;render()});
 document.querySelectorAll('[data-save-pathway]').forEach(el=>el.onclick=()=>{state.savedPathways||=[];if(!state.savedPathways.includes(el.dataset.savePathway))state.savedPathways.push(el.dataset.savePathway);save();render()});
 document.querySelectorAll('[data-replace-pathway]').forEach(el=>el.onchange=()=>{if(!el.value)return;const rec=currentRecommendations();if(rec.some(m=>m.name===el.value))return toast('Choose a distinct direction.');rec[+el.dataset.replacePathway]=E.majors.find(m=>m.name===el.value);state.results=rec.map(m=>({name:m.name}));save();render()});
 document.querySelectorAll('[data-load-quiz]').forEach(el=>el.onclick=()=>{const run=state.quizHistory[+el.dataset.loadQuiz];state.answers=[...(run.answers||[])];state.results=currentRecommendations().map(m=>({name:m.name,programId:m.programId,institution:m.institution}));state.compare=currentRecommendations().map(m=>m.key);save();location.hash='explore';render()});
 document.querySelector('#college-search')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);productFilters={query:String(f.get('query')||''),kind:f.get('kind')};render()});
 document.querySelectorAll('[data-compare-college]').forEach(el=>el.onchange=()=>{const list=new Set(state.collegeCompare||[]);if(el.checked){if(list.size===3){el.checked=false;return toast('Compare up to three institutions.')}list.add(el.dataset.compareCollege)}else list.delete(el.dataset.compareCollege);state.collegeCompare=[...list];save();render()});
 document.querySelectorAll('[data-target-college]').forEach(el=>el.onclick=()=>{recordPlanChange('Target university changed. Prior earned courses are retained; institutional requirements must be checked again.');state.profile={...state.profile,target:el.dataset.targetCollege,calendar:ProductCore.institutions.find(u=>u.name===el.dataset.targetCollege).calendar};save();location.hash='profile';render()});
 document.querySelector('#p-target')?.addEventListener('change',e=>{const entry=ProductCore.institutions.find(u=>u.name===e.target.value);if(entry)document.querySelector('#p-calendar').value=entry.calendar});
 document.querySelector('#product-profile')?.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));Object.assign(f,resolveCatalogDirection(f.major,f.target));if(f.primaryProgramId&&!attachCatalogGoal(f))return;f.summer=e.target.elements.namedItem('summer').checked;f.preferCommunity=e.target.elements.namedItem('preferCommunity').checked;const expectedCalendar=ProductCore.institutions.find(u=>u.name===f.target)?.calendar;if(expectedCalendar&&f.calendar!==expectedCalendar){document.querySelector('#profile-error').textContent='Use the '+expectedCalendar.toLowerCase()+' calendar for this institution; no credit conversion is inferred.';return}if(f.startTerm==='Summer'&&!f.summer){document.querySelector('#profile-error').textContent='Enable summer terms or choose another starting term.';return}if(f.calendar==='Semester'&&f.startTerm==='Winter'){document.querySelector('#profile-error').textContent='Choose Fall, Spring or Summer for a semester plan.';return}recordPlanChange('Goals, major, institution or scheduling preferences updated. The roadmap was rebuilt; completed courses were retained.');state.profile={...state.profile,...f};state.historyDone=true;mode=f.load;save();location.hash='roadmap';render()});
 const courseForm=resetProductForm('#course-form');courseForm?.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const prereqs=String(f.prereqs||'').split(',').map(x=>x.trim().toUpperCase()).filter(Boolean),code=f.code.trim().toUpperCase();if(prereqs.includes(code))return toast('A course cannot require itself.');const incoming={...f,code,units:state.profile?.calendar==='Semester'?'Semester':'Quarter',credits:+f.credits,prereqs,completed:e.target.elements.namedItem('completed').checked,status:e.target.elements.namedItem('completed').checked?'Completed':'Planned',term:f.term||''};if(state.courses.some(c=>c.code===code&&c.institution===f.institution&&c.term===incoming.term))return toast('This same course attempt is already saved. Update its status below.');recordPlanChange('Course added: '+code+'. Prerequisite and credit-load checks rerun.');state.courses.push(incoming);state.historyDone=true;save();render()});
 document.querySelectorAll('[data-record-status]').forEach(el=>el.onchange=()=>{const c=state.courses[+el.dataset.recordStatus];recordPlanChange(c.code+' changed to '+el.value+'. Earned-credit and prerequisite checks rerun; attempt history retained.');c.status=el.value;c.completed=el.value==='Completed';if(el.value==='Failed'){c.grade='F';c.attemptStatus='failed'}if(el.value==='Dropped'){c.completed=false}save();render()});
 document.querySelectorAll('[data-record-grade]').forEach(el=>el.onchange=()=>{const c=state.courses[+el.dataset.recordGrade];recordPlanChange('Grade updated for '+c.code+'. Minimum-grade checks rerun.');c.grade=el.value;save();render()});
 document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{const c=state.courses[+el.dataset.remove];if(!c||!confirm('Remove '+c.code+' from the active record? A copy remains in removed-course history.'))return;state.removedCourses||=[];state.removedCourses.push({...c,removedAt:new Date().toISOString()});recordPlanChange(c.code+' removed explicitly. A copy was retained in history.');state.courses.splice(+el.dataset.remove,1);save();render()});
 document.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>{recordPlanChange('Workload changed to '+el.dataset.mode+'. The roadmap was rebuilt.');mode=el.dataset.mode;state.profile||={};state.profile.load=mode;save();render()});
 document.querySelector('#product-scenario')?.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),candidate=JSON.parse(JSON.stringify(state));const direction=resolveCatalogDirection(f.major,f.target);f.major=direction.major;f.target=direction.target;candidate.profile={...candidate.profile,...direction,major:f.major,target:f.target,load:f.load,year:f.year,summer:e.target.elements.namedItem('summer').checked,calendar:ProductCore.institutions.find(u=>u.name===f.target)?.calendar||'Quarter'};candidate.manual=null;if(f.repeat){candidate.courses=candidate.courses.filter(c=>c.code!==f.repeat);candidate.creditLedger=(candidate.creditLedger||[]).filter(c=>c.code!==f.repeat);candidate.courses.forEach(c=>{if(c.creditOrigins)c.creditOrigins=c.creditOrigins.filter(o=>o.code!==f.repeat)})}const base=productBuildPlan(state,mode),proposal=productBuildPlan(candidate,f.load,false);state.scenarios||=[];state.scenarios.push({name:f.name,at:new Date().toISOString(),profile:candidate.profile,repeat:f.repeat,supported:proposal.supported,delta:ProductCore.diff(base,proposal),courses:proposal.courses});save();render();toast('Comparison saved. Your original goals and academic record are unchanged.')});
 document.querySelector('#milestone-form')?.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.source&&!ProductCore.safeURL(f.source))return toast('Use an HTTPS official source link.');state.milestones||=[];state.milestones.push({...f,done:false,verification:'Personal planning date — not verified',savedAt:new Date().toISOString()});save();render();toast('Milestone saved in your workspace. No notification has been scheduled.')});
 document.querySelectorAll('[data-milestone-done]').forEach(el=>el.onchange=()=>{state.milestones[+el.dataset.milestoneDone].done=el.checked;save()});
 document.querySelectorAll('[data-milestone-delete]').forEach(el=>el.onclick=()=>{state.milestones.splice(+el.dataset.milestoneDelete,1);save();render()});
 document.querySelectorAll('[data-milestone-calendar]').forEach(el=>el.onclick=()=>{const m=state.milestones[+el.dataset.milestoneCalendar];try{download('camino-milestone.ics',AdmissionReadiness.calendar.generate([m],{personal:true}),'text/calendar');toast('Calendar file downloaded. Import it into your calendar app to set reminders.')}catch(error){toast(error.message)}});
 const restore=resetProductForm('#restore-workspace');restore?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Backup must be under 2 MB.');const incoming=WorkspaceSchema.validate(JSON.parse(await file.text()));if(!confirm('Replace this browser workspace with the validated backup? Export a backup first if needed.'))return;state=incoming;state.historyDone||=state.courses.length>0;mode=state.profile?.load||'Balanced';AcademicPathway.normalizeState(state);save();location.hash='roadmap';render();toast('Workspace restored.')}catch(err){toast(err.message)}});
 resetProductForm('#delete-data')?.addEventListener('click',async()=>{const deleted=await deleteWorkspace();if(!deleted)return;globalThis.caminoRecoveryError=null;globalThis.caminoRecoveryRaw=null;try{sessionStorage.removeItem('camino-quiz-session')}catch{}});
 document.querySelector('#export-data')?.addEventListener('click',()=>download('camino-workspace.json',JSON.stringify(state,null,2)));
}
function installProduct(){
 const originalRender=render;render=()=>{try{originalRender()}catch(err){const main=document.querySelector('#main');if(main){main.inert=false;main.innerHTML=`<section class="error-boundary" role="alert"><h1>We couldn’t open this view.</h1><p>Your saved workspace has not been cleared. Try another page or export a backup from My Account.</p><p>${esc(err.message)}</p><a class="btn" href="#account">Open My Account</a><a class="btn" href="#home">Return home</a></section>`;}console.error('Camino view error:',err)}};
 const originalBanner=accountBanner;accountBanner=()=>`${globalThis.caminoRecoveryError?'<div class="save-warning" role="alert">The saved workspace could not be read. Its original text is retained for recovery. <button class="btn" id="recover-workspace">Download original data</button></div>':''}${originalBanner()}`;

 const menu=document.querySelector('#nav-toggle');if(menu)menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('#primary-nav')?.classList.toggle('is-open',open)};document.querySelectorAll('#primary-nav a').forEach(a=>a.addEventListener('click',()=>{menu?.setAttribute('aria-expanded','false');document.querySelector('#primary-nav')?.classList.remove('is-open')}));
 home=productHome;question=productQuestion;results=productResults;profile=productProfile;applications=productMilestones;scenarios=productScenarios;privacy=productPrivacy;termName=i=>ProductCore.termName(state.profile||{},i);
 const oldDiscover=discover;discover=()=>{let page=oldDiscover().replace('THE CAMINO PATHFINDER','DISCOVER YOUR DIRECTION').replace('Quick Discovery','12-step Discovery').replace('Full Discovery','32-step Discovery');let draft;try{draft=ProductCore.quizDraft(JSON.parse(sessionStorage.getItem('camino-quiz-session')||'null')||state.quizDraft)}catch{}if(draft&&draft.answers.length<draft.length)page=page.replace('<div class="pathfinder-modes">',`<button class="btn primary" id="resume-quiz">Resume your quiz · ${draft.answers.length} of ${draft.length} answered →</button><div class="pathfinder-modes">`);return page};
 const oldSources=sources;sources=()=>oldSources().replace('ChatGPT accounts and private workspace sync enabled',standaloneMode?'standalone browser storage; account backend not configured':'Sites private account sync')+equivalencyRegister();
 const oldHistory=academicHistory;academicHistory=()=>oldHistory().replace('Quarter credits',state.profile?.calendar==='Semester'?'Semester credits (manual entry)':'Quarter credits').replace('Grade / term (optional)','Grade (optional)').replace('placeholder="3.5 / Autumn 2026"','placeholder="3.5 or B+"').replace('</div></div><label><input name="completed"','</div><div><label for="course-term">Term (optional)</label><input id="course-term" name="term" maxlength="60" placeholder="Fall 2026"></div></div><label><input name="completed"')+`<div class="page history-controls">`+recordStatusControls()+`<details class="card"><summary>Explicitly removed course history (${(state.removedCourses||[]).length})</summary>${(state.removedCourses||[]).map(c=>`<p>${esc(c.code)} · ${esc(c.institution)} · ${esc(c.grade)} · ${esc(c.term)}</p>`).join('')||'<p>No course records have been explicitly removed.</p>'}</details></div>`;
 const oldRoadmap=roadmap;roadmap=()=>{if(!state.profile)return page('YOUR ROADMAP','Choose a direction first.',`<p>Start with your goals; transcript upload is optional.</p><div class="actions">${btn('Set my goals','profile',true)}${btn('Preview an example','preview')}</div>`);return oldRoadmap()};
 moveCourse=(code,term)=>{if(!Number.isInteger(term)||term<0||term>47)return toast('Choose term 1–48.');const plan=productBuildPlan(),next=plan.courses.map(c=>({...c,term:c.code===code?term:c.term}));const errors=ProductCore.validatePlan(next,plan.supported?plan.done:E.completedCodes(state.courses,state.profile?.target),state.profile||{},{Balanced:15,Flexible:10,Accelerated:20}[mode]);if(errors.length)return toast('Move not saved: '+errors[0]);state.manual=next;state.manualMode=mode;state.manualSignature=ProductCore.signature(state,mode);state.planChanges||=[];state.planChanges.unshift({at:new Date().toISOString(),message:code+' moved to '+termName(term)+'. Prerequisites, co-requisites, seasons and workload rechecked.'});save();render();toast('Adjusted schedule saved.')};
 const originalBind=bind;bind=()=>{originalBind();bindProduct()};
 chooseMajor=value=>{const catalog=String(value).startsWith('catalog:')?resolveCatalogDirection(value):null;if(!catalog&&!E.majors.some(m=>m.name===value))return;if(catalog&&!attachCatalogGoal(catalog))return;recordPlanChange('Direction changed; completed courses retained and degree coverage rechecked.');state.profile={...state.profile,...(catalog||{major:value,primaryProgramId:''})};save();location.hash='profile';render()};
}
function equivalencyRegister(){const rows=ProductCore.mappings(E,AcademicPathway);return `<section class="page"><h2>Structured equivalency evidence</h2><p class="muted">Catalog year is unresolved unless explicitly provided. Credit transfer, general education and major applicability are separate decisions.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Equivalency evidence register"><table><thead><tr><th>Source</th><th>Destination</th><th>Applicability</th><th>Effective / catalog year</th><th>Verification & restrictions</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.sourceInstitution)}<br>${esc(r.sourceCourse)}</td><td>${esc(r.destinationInstitution)}<br>${esc(r.destinationCourse)}</td><td>${esc(r.applicability)}</td><td>${esc(r.effective)}<br>Catalog year: ${r.catalogYear||'Confirm with receiving institution'}</td><td>${esc(r.status)}<br>Last reviewed ${esc(r.lastVerified)}<br>${esc(r.restrictions)}<br><a href="${r.url}" class="text-link" target="_blank" rel="noopener">Official source ↗</a></td></tr>`).join('')}</tbody></table></div><p>Equivalency not verified — confirm with the receiving institution for every route absent from this register.</p></section>`}
